"""The stage-s limit-computable decoder, and the finite-patching repair.

A(m, 0) = 0,  A(m, k+1) = f(k) if obs(k) == m else A(m, k).

A is computable in (m, s) and satisfies A(obs(x), s) = f(x) for every s > x, so
every fibre-constant quantity has a limit-computable decoder with an explicit
modulus.  Recognising that the sequence has stabilised is the single jump that
separates limit computability from computability.

The repair routine implements the finite-patching principle: a decoder wrong on
only finitely many records can be corrected into a perfect one, so a channel with
no perfect computable decoder forces infinitely many errors.
"""

from __future__ import annotations

from typing import Callable, Dict, List, Optional

Channel = Callable[[int], int]
Quantity = Callable[[int], int]
Decoder = Callable[[int], int]


def approx_decoder(obs: Channel, f: Quantity, m: int, s: int) -> int:
    """Stage-s approximation to the decoded value of record m.  Cost O(s)."""
    value = 0
    for k in range(s):
        if obs(k) == m:
            value = f(k)
    return value


def stabilisation_stage(obs: Channel, f: Quantity, x: int, cap: int) -> Optional[int]:
    """Least s <= cap after which the approximation on obs(x) never changes."""
    for s in range(cap + 1):
        if all(approx_decoder(obs, f, obs(x), t) == f(x) for t in range(s, cap + 1)):
            return s
    return None


def patch(dec: Decoder, corrections: Dict[int, int]) -> Decoder:
    """Overwrite a decoder at finitely many records; the result stays computable."""
    table = dict(corrections)

    def patched(y: int) -> int:
        return table[y] if y in table else dec(y)
    return patched


def repair(obs: Channel, f: Quantity, dec: Decoder, window: int) -> Decoder:
    """Correct a decoder on all records it gets wrong below the window."""
    corrections: Dict[int, int] = {}
    for n in range(window):
        if dec(obs(n)) != f(n):
            corrections[obs(n)] = f(n)
    return patch(dec, corrections)


def error_records(obs: Channel, f: Quantity, dec: Decoder, window: int) -> List[int]:
    """Distinct records below the window that the decoder decodes incorrectly."""
    return sorted({obs(n) for n in range(window) if dec(obs(n)) != f(n)})


if __name__ == "__main__":
    obs: Channel = lambda n: (n * 5) % 13
    f: Quantity = lambda n: ((n * 5) % 13) ** 2

    print("stabilisation stages for x = 0..9:",
          [stabilisation_stage(obs, f, x, 40) for x in range(10)])
    print("modulus s > x verified:",
          all(approx_decoder(obs, f, obs(x), s) == f(x)
              for x in range(25) for s in range(x + 1, x + 10)))

    sloppy: Decoder = lambda m: 0 if m in (3, 7, 11) else (m ** 2)
    print("bad records:", error_records(obs, f, sloppy, 300))
    fixed = repair(obs, f, sloppy, 300)
    print("repaired decoder is perfect:",
          all(fixed(obs(n)) == f(n) for n in range(300)))

